{
  "spells": [
    {
      "id": "spell_light_07",
      "theory": "清影线把魔力送进受术墙面表层，沿微孔与划痕排列成一层极薄的感光纹。光线斜触墙面时，纹路让凹凸处的明暗分界更锐利，投影边缘因此显出一条可描摹的细线。它不改变物体本身，也不让黑暗处发亮，只在日照或灯照下把模糊的轮廓收窄，供制图者用炭笔沿边勾画。",
      "casting": "以食指与中指并拢，在墙面上从投影一端匀速划到另一端，同时沿指腹送出细流魔力；收指时轻叩墙面一次，让纹路闭合。",
      "failure": "魔力送得过快时，纹路会断续成虚线段，投影边缘反而出现重影，测量者若照描会得到偏斜的线。墙面潮湿时，纹路可能整片滑落，只留下几处亮斑，需要等墙干后重画。",
      "counters": [
        "用湿布擦过墙面，表层纹路被水膜覆盖而暂时失效。",
        "在纹路上覆一层薄灰或炭粉，感光差异被填平，清影线不再显线。"
      ],
      "socialConsequences": "石匠和造船匠欢迎它来校验曲板与墙角的弧度，省下反复拉绳的工夫。卖绳墨与直尺的商人担心常客少买耗材，但仍能供应木料上用的墨斗。乡约见证地界时，双方若用它描画界墙投影，须先征得墙主同意；往他人墙上刻画而未告知，会被视作毁损墙面的纠纷。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时纹路常断成虚点，只能描出较直的短边。",
        "环线稳定后，曲板与墙角投影可一次描完。",
        "熟练者能在斜光下保持线条不重影，减少复描。",
        "更高熟练度让纹路在粗糙石面上也均匀显线。"
      ]
    },
    {
      "id": "spell_light_08",
      "theory": "光幕术把魔力铺在指定一侧的空气薄层里，让穿过它的光线向旁偏折，形成一片柔和亮幕。幕面不挡声，因为声波振动不被这层偏折影响；它也不产生热，只是把视线搅成朦胧的亮白。幕的大小随施术者划定的边界而定，边界之外的空气保持原样。",
      "casting": "双臂在身前张开，掌心相对，从肩宽慢慢拉至所需宽度；同时以拇指在空气中勾出上缘弧线，停顿一息让幕面凝定。",
      "failure": "魔力分布不匀时，幕面会出现透明空洞，对面的人能从洞中看清这边。若拉得过猛，亮幕会碎成几团浮光，几息后自行消散，期间反而暴露施术者的位置。",
      "counters": [
        "从侧面绕到幕缘之外，偏折层不覆盖斜向视线。",
        "用强风搅乱薄层空气，幕面被吹散成断续光斑。"
      ],
      "socialConsequences": "集市摊主用它隔开试穿衣物的角落，既省布帘又不妨碍招呼客人。布帘商贩担心生意被分走，却仍能卖挡风防雨的厚帘。城卫若见有人在窄巷反复张幕遮挡巡逻视线，会要求说明用途；港务对遮挡航道信号的行为另有追究，普通店前遮阳一般不在此列。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时光幕边缘发虚，常留出可被看见的缝隙。",
        "掌握均匀铺展后，幕面能遮住一侧的寻常视线。",
        "熟练者可按门框宽度精确收边，减少漏光空洞。",
        "更高熟练度让幕面在微风中保持平整不碎散。"
      ]
    },
    {
      "id": "spell_light_09",
      "theory": "镜面步标把魔力封进一小块树脂，使其沿施术者走过的已知路径留下微弱光点。光点只标记已经踏过的地面与转角，不会自行延伸向未探索的方向。树脂中的魔力缓慢消耗，光点随时间变暗；若路线中断或从未走过，步标便无处可附，只能停在起点附近。",
      "casting": "取一粒树脂夹在拇指与食指间，每走一步轻捻一下，让光点落在脚后跟位置；走完预定路线后，把剩余树脂按在终点地面。",
      "failure": "树脂捻得太碎时，光点会密集堆在一处，后来者看到一团亮斑却找不到正确转角。若在岔路口漏捻，整条标记会断成两截，追踪者可能沿错误方向走进死路。",
      "counters": [
        "用脚扫过光点或撒沙覆盖，树脂标记被遮住而难以辨认。",
        "沿路洒水使树脂受潮，光点提前变暗直至消失。"
      ],
      "socialConsequences": "商队向导用它为后队标注水源与岔路，减少在河谷走散的风险。抄近路的猎人担心自己的私径被标出，常向向导打听标记终点。乡约允许在公共道路上留短期步标，但若把光点引向他人宅院或晒场，须先取得主人同意；港务对在码头货堆间留标导致绊倒事故的，会按货损追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时步标间距忽大忽小，追踪者需反复辨认。",
        "间距均匀后，后队能沿光点顺利走到终点。",
        "熟练者能在岔路口准确加标，减少走错支路。",
        "更高熟练度让光点在湿地与石面上都清晰可辨。"
      ]
    }
  ]
}
